section.r6_class_object.code1:
Person <- R6Class("Person",
  public = list(
    name = NULL,
    age = NULL,
    initialize = function(name, age) {
      self$name <- name
      self$age <- age
    },
    greet = function() {
      cat("哈囉，我是", self$name, "，我", self$age, "歲了。\n")
    }
  )
)

alice <- Person$new("Alice", 25)
alice$greet()

section.r6_encapsulation.code1:
SecurePerson <- R6Class("SecurePerson",
  public = list(
    name = NULL,
    initialize = function(name, password) {
      self$name <- name
      private$password <- password
    },
    checkPassword = function(p) {
      p == private$password
    }
  ),
  private = list(
    password = NULL
  )
)

bob <- SecurePerson$new("Bob", "1234")
bob$checkPassword("1234")
## [1] TRUE
bob$password
## 錯誤：找不到物件 'password'

section.r6_inheritance.code1:
Student <- R6Class("Student",
  inherit = Person,
  public = list(
    grade = NULL,
    initialize = function(name, age, grade) {
      super$initialize(name, age)
      self$grade <- grade
    },
    greet = function() {
      cat("哈囉，我是", self$name, "，是一位", self$grade, "學生。\n")
    }
  )
)

charlie <- Student$new("Charlie", 20, "college")
charlie$greet()
